protected void init()
{
    api = XAPI_APIS::GetAgreements;
    super();
}

protected void postRun()
{
    EGS_API_DataContract_Response res;

    if (!responseText)
    {
        return;
    }

    res      = FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response), responseText);
    logKey   = "GetAgreement";
    logValue = res.parmMessage();
}

protected str body()
{
    Map configMap = new Map(Types::String, Types::String);

    configMap.insert('<DataAreaId>',    curExt());
    configMap.insert('<accountNum>',    XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateCustomer, 'CustAccount'));
    configMap.insert('<delPointRecId>', XAPI_APILogTable::getValueByKey(XAPI_APIS::GetLocations, 'DelPointRecId'));

    return this.prepareBody(configMap);
}
